package com.nosferatu.divinemachinerylegacy.gui;import com.nosferatu.divinemachinerylegacy.DivineMachineryLegacy;import com.nosferatu.divinemachinerylegacy.botania.MachineTier;import com.nosferatu.divinemachinerylegacy.tile.TileMechanicalDaisy;import net.minecraft.client.gui.inventory.GuiContainer;import net.minecraft.client.renderer.Tessellator;import net.minecraft.entity.player.InventoryPlayer;import net.minecraft.util.ResourceLocation;import org.lwjgl.opengl.GL11;
public class GuiMechanicalDaisy extends GuiContainer{private final TileMechanicalDaisy tile;private static final ResourceLocation[] G={t("textures/gui/reforked/base_mechanical_daisy.png"),t("textures/gui/reforked/upgraded_mechanical_daisy.png"),t("textures/gui/reforked/advanced_mechanical_daisy.png"),t("textures/gui/reforked/ultimate_mechanical_daisy.png")};private static final ResourceLocation[] I={t("textures/gui/reforked/inventory_modules/base_inventory.png"),t("textures/gui/reforked/inventory_modules/upgrade_inventory.png"),t("textures/gui/reforked/inventory_modules/advanced_inventory.png"),t("textures/gui/reforked/inventory_modules/ultimate_inventory.png")};private static final ResourceLocation W=t("textures/gui/reforked/misc/current_water.png");public GuiMechanicalDaisy(InventoryPlayer p,TileMechanicalDaisy q){super(new ContainerMechanicalDaisy(p,q));tile=q;xSize=216;ySize=231;}@Override protected void drawGuiContainerForegroundLayer(int x,int y){int off=tile.getTier()==MachineTier.CRIMSON?0:10;fontRendererObj.drawString("Mechanical Daisy - "+name(tile.getTier()),off+8,6,0x303030);fontRendererObj.drawString("Slot size: "+tile.getSlotLimit(),off+69,105,0x303030);fontRendererObj.drawString("Water: "+tile.getWater()+" / "+tile.getWaterCapacity(),off+33,116,0x24535a);}@Override protected void drawGuiContainerBackgroundLayer(float f,int x,int y){GL11.glColor4f(1,1,1,1);MachineTier tier=tile.getTier();int off=tier==MachineTier.CRIMSON?0:10,mw=tier==MachineTier.CRIMSON?216:196,mh=tier==MachineTier.CRIMSON?134:124;mc.getTextureManager().bindTexture(G[tier.ordinal()]);drawTexturedModalRect(guiLeft+off,guiTop,0,0,mw,mh);mc.getTextureManager().bindTexture(I[tier.ordinal()]);drawTexturedModalRect(guiLeft+14,guiTop+136,0,0,188,95);int width=(int)Math.round(130*Math.min(1D,tile.getWater()/(double)tile.getWaterCapacity()));if(width>0){mc.getTextureManager().bindTexture(W);Tessellator q=Tessellator.instance;q.startDrawingQuads();double u=width/130D;int px=guiLeft+off+33,py=guiTop+105;q.addVertexWithUV(px,py+5,zLevel,0,1);q.addVertexWithUV(px+width,py+5,zLevel,u,1);q.addVertexWithUV(px+width,py,zLevel,u,0);q.addVertexWithUV(px,py,zLevel,0,0);q.draw();}}private static ResourceLocation t(String p){return new ResourceLocation(DivineMachineryLegacy.MODID,p);}private static String name(MachineTier t){String k=t.getKey();return Character.toUpperCase(k.charAt(0))+k.substring(1);}}
